input.command:
IMPLEMENT_TMPDIR="<TMPDIR>"
CLAUDE_PLUGIN_ROOT=$(awk 'BEGIN{p="LARCH_CLAUDE_PLUGIN_ROOT="} index($0,p)==1{print substr($0,length(p)+1); exit}' "$IMPLEMENT_TMPDIR/session-env.sh" 2>/dev/null || true)
export CLAUDE_PLUGIN_ROOT IMPLEMENT_TMPDIR
_launch_id="run-step2-dispatch.49907"
export LARCH_BREADCRUMB_STREAM="$IMPLEMENT_TMPDIR/breadcrumbs/run-step2-dispatch.${_launch_id}.ndjson"
export LARCH_DONE_SENTINEL=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.done.* 2>/dev/null | head -1)
export LARCH_STATUS_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.status.* 2>/dev/null | head -1)
export LARCH_QUIET_LOG_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.quiet.* 2>/dev/null | head -1)
export LARCH_BREADCRUMBS_SURFACED_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.surfaced.* 2>/dev/null | head -1)

echo "Launching run-step2-dispatch.sh with coder=codex"
